fn prefix_all(prefix: String, items: Vec<String>) -> Vec<String> {
    let mut out = Vec::new();
    for item in items {
        let combined = prefix + &item;
        out.push(combined);
    }
    out
}

fn main() {
    let v = vec![String::from("alice"), String::from("bob")];
    for s in prefix_all(String::from("hi "), v) {
        println!("{}", s);
    }
}
